idth:63px;overflow:hidden;position:relative;border-radius:12px;background:linear-gradient(#37354e,#d5a5b5)}.preview-doll svg{width:100%;position:absolute;bottom:-6px}.custom-field{margin:13px 0}.custom-field label{display:block;font-size:10px;font-weight:700;margin-bottom:7px}.name-input{width:100%;border:1px solid #e9dfe4;border-radius:10px;padding:10px 11px;font:inherit;font-size:12px;outline:none}.name-input:focus{border-color:#cc91a7}.swatches{display:flex;gap:9px}.swatch{width:27px;height:27px;border:2px solid white;box-shadow:0 0 0 1px #e6dce2;border-radius:50%;padding:0}.swatch.selected{box-shadow:0 0 0 2px #b36e89}.option-buttons{display:flex;gap:7px}.option-pill{border:1px solid #eadfe4;background:#fff;border-radius:9px;padding:7px 9px;font-size:9px}.option-pill.selected{background:#f6eaf0;border-color:#d8afbf;color:#9c5e79}.call-stage{min-height:240px;display:grid;place-items:center;border-radius:17px;background:linear-gradient(150deg,#2d304b,#6c5677 62%,#bd8da6);color:white;margin:14px 0;position:relative;overflow:hidden}.call-stage:before{content:'✦  ·  ✧';position:absolute;top:24px;left:22px;letter-spacing:18px;color:#fff8}.call-portrait{width:130px;height:173px;position:relative;overflow:hidden}.call-portrait svg{width:100%;height:100%}.call-video{position:absolute;right:12px;bottom:12px;width:75px;height:95px;object-fit:cover;border-radius:12px;background:#322d3b;border:2px solid #fff9;transform:scaleX(-1)}.call-controls{display:flex;justify-content:center;gap:13px}.round-control{width:42px;height:42px;border:0;border-radius:50%;background:#f5edf1;color:#855e74;font-size:16px}.round-control.active{background:#be7893;color:white}.round-control.end-call{background:#c95265;color:#fff}.call-caption{text-align:center;color:#fff;font:500 15px 'Playfair Display',serif;position:absolute;bottom:20px}.expression-row{display:flex;gap:7px;margin-top:9px}.expression-button{flex:1;padding:8px 4px;border:1px solid #eee2e8;background:#fff;border-radius:9px;font-size: