(() => {
  const $ = (s) => document.querySelector(s);
  const SAVE_KEY = 'moonlit-save-v1';
  const defaults = { name: 'Astra', hair: 0, outfit: 0, eyes: 0, overlay: false, bond: 12, memories: [{ title: 'The first hello', text: 'A quiet rooftop, a sky full of stars, and the start of something.' }], turn: 0, sound: true };
  let save = { ...defaults, ...(JSON.parse(localStorage.getItem(SAVE_KEY) || 'null') || {}) };
  let stream = null, callOpen = false, expressionTimer = null, toastTimer = null;
  const hairColors = [['#483a68','#9c78b4'],['#713d58','#db8aa0'],['#3d5264','#8cb1bd'],['#79513d','#d5a779']];
  const outfits = [['#f3a5b4','#bc7997'],['#a9a0d5','#716caa'],['#8dc6b4','#558b83']];
  const eyeColors = ['#5b638e','#56857c','#9a6386'];
  const story = [
    { title:'Getting to know you', scene:'Under the<br><em>same stars.</em>', desc:'The city hums below. Astra turns toward you, a question hiding in her smile.', line:'The city looks softer from up here. Do you ever wish you could pause a moment?', bubble:"I was hoping<br>you'd stay a little.", choices:[
      {text:'“Only the good ones. This feels like one.”', response:'Then let’s be selfish with this one. Just a little longer.', bond:8, mood:'quietly delighted', memory:'A moment worth keeping', note:'You told Astra this moment was one to keep. She smiled all the way home.'},
      {text:'“I’d rather see what happens next.”', response:'I like that. You make the unknown feel less scary somehow.', bond:6, mood:'curious', memory:'A little faith in tomorrow', note:'You reminded Astra that the best parts might still be ahead.'},
      {text:'“Maybe. What would you pause?”', response:'This. The breeze, the lights… and you asking me that.', bond:10, mood:'warm and hopeful', memory:'Her favorite answer', note:'Astra said she would pause this exact moment—with you in it.'}
    ]},
    { title:'A softer kind of brave', scene:'Tell me<br><em>something true.</em>', desc:'A breeze catches Astra’s hair. The question is gentle, but she means it.', line:'Can I ask you something a little real? What makes you feel most like yourself?', bubble:'No perfect answer<br>needed. Promise.', choices:[
      {text:'“When I’m making something, even if it’s messy.”', response:'Messy beginnings are still beginnings. I think that’s beautiful.', bond:8, mood:'admiring', memory:'A thing you make', note:'You shared what brings you alive. Astra wants to hear more about it.'},
      {text:'“When I can make someone feel seen.”', response:'You’re very good at that, you know. I feel seen right now.', bond:10, mood:'touched', memory:'Seen, and understood', note:'Astra felt a little less alone after your answer.'},
      {text:'“I’m still figuring that out, honestly.”', response:'Me too. Maybe figuring it out counts as being yourself.', bond:7, mood:'gentle', memory:'Still becoming', note:'You and Astra agreed there’s no rush to have everything figured out.'}
    ]},
    { title:'A tiny wish', scene:'The night is<br><em>still young.</em>', desc:'Astra leans on the railing. Far below, one window after another glows gold.', line:'If we could go anywhere together tomorrow, where would you take me?', bubble:'Somewhere with<br>a good view?', choices:[
      {text:'“A tiny bookshop, then coffee and no plans.”', response:'You had me at tiny bookshop. I’ll find us the coziest corner.', bond:9, mood:'dreamy', memory:'A date for another day', note:'Your dream date: a bookshop, good coffee, and nowhere else to be.'},
      {text:'“Somewhere by the water at sunrise.”', response:'I want to hear the world wake up with you. That sounds perfect.', bond:10, mood:'wistful', memory:'The sunrise promise', note:'Astra is holding onto your promise to watch the sunrise together.'},
      {text:'“Surprise me. I like seeing what you love.”', response:'Then I’ll show you my favorite hidden place. It’s a little secret.', bond:8, mood:'excited', memory:'A secret place', note:'Astra promised to share one of her favorite places with you.'}
    ]},
    { title:'A little closer', scene:'Stay for<br><em>one more.</em>', desc:'Astra looks at you with a new kind of ease. The stars don’t seem so far away.', line:'I used to think being understood would feel like fireworks. It’s quieter than that, isn’t it?', bubble:'This is nice.<br>Just us.', choices:[
      {text:'“Quiet can be its own kind of magic.”', response:'Then let’s not rush past it. I’m really glad you’re here.', bond:10, mood:'at ease', memory:'A quieter kind of magic', note:'You found something special in a quiet moment together.'},
      {text:'“I’m glad it feels safe to be real with me.”', response:'It does. More than I expected. Thank you for making room for that.', bond:11, mood:'deeply grateful', memory:'A safe place', note:'Astra trusts you with the parts of herself she usually keeps hidden.'},
      {text:'“Maybe the fireworks come later.”', response:'I hope so. But this is a pretty wonderful beginning.', bond:8, mood:'playful', memory:'Just the beginning', note:'Astra thinks this is only the beginning of your story.'}
    ]}
  ];
  function persist(){ localStorage.setItem(SAVE_KEY, JSON.stringify(save)); }
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
  function activeStory(){return story[Math.min(save.turn,story.length-1)]}
